WITH cleaned AS (SELECT id, customer_id, browser, started_at, country, CONCAT_WS('-', country, browser) AS country_browser_key, SUBSTRING(browser, 1, 4) AS browser_prefix FROM sessions WHERE started_at > TIMESTAMP '2024-02-18 07:00:00') SELECT s.*, x.event_type, x.web_event_page FROM cleaned s JOIN LATERAL (SELECT c.event_type, c.page AS web_event_page FROM web_events c WHERE c.session_id = s.id ORDER BY c.event_time DESC, c.id DESC LIMIT 1) x ON TRUE;
